    `status_reason` from {{ ref('int_opportunity_periods') }} where model_run_id={{ ch_literal(var('model_run_id','parse_only')) }}), origins as (select tenant_id,opportunity_id,opportunity_key,argMin(tuple(created_at,sale_type_id),valid_from_at) as first,min(valid_from_at) as first_at from p group by tenant_id,opportunity_id,opportunity_key), histories as (select tenant_id,opportunity_id,groupArray(tuple(stage_id,entered_at,first_observed_at,visit_key)) as visits,max(source_published_at) as lineage_published,arraySort(arrayDistinct(arrayFlatten(groupArray(source_version_keys)))) as lineage_keys from {{ ref('int_opportunity_stage_visits') }} where model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} group by tenant_id,opportunity_id), anchors as (select o.tenant_id as tenant_id,o.opportunity_id as opportunity_id,o.opportunity_key as opportunity_key,o.first.1 as created_at,o.first.2 as origin_type,o.first_at,d.`followup_definition_id` AS `followup_definition_id`,
    d.`followup_definition_key` AS `followup_definition_key`,
    d.`followup_definition_version_key` AS `followup_definition_version_key`,
    d.`definition_rule_version` AS `definition_rule_version`,
    d.`followup_kind` AS `followup_kind`,
    d.`sale_type_id` AS `sale_type_id`,
    d.`source_stage_id` AS `source_stage_id`,
    d.`target_stage_id` AS `target_stage_id`,
    d.`horizon_days` AS `horizon_days`,
    d.`funnel_position` AS `funnel_position`,
    d.`previous_target_stage_id` AS `previous_target_stage_id`,
    d.`anchor_rule` AS `anchor_rule`,
    d.`population_rule` AS `population_rule`,
    d.`attribution_rule` AS `attribution_rule`,
    d.`maturity_rule` AS `maturity_rule`,
    d.`is_enabled` AS `is_enabled`,
    d.`definition_status` AS `definition_status`,h.visits as visits,if(d.followup_kind='stage_transition' and d.source_stage_id!=0,arrayReduce('minOrNull',arrayMap(x->x.2,arrayFilter(x->x.1=d.source_stage_id and x.2 is not null,h.visits))),o.first.1) as anchor from origins o inner join {{ ref('dim_followup_definition') }} d on d.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and o.tenant_id=d.tenant_id and o.first.2=d.sale_type_id and d.is_enabled left join histories h on o.tenant_id=h.tenant_id and o.opportunity_id=h.opportunity_id), horizons as (select `tenant_id`,
    `opportunity_id`,
    `opportunity_key`,
    `created_at`,
    `origin_type`,
    `first_at`,
    `followup_definition_id`,
