    `anchor_rule`,
    `population_rule`,
    `attribution_rule`,
    `maturity_rule`,
    `is_enabled`,
    `definition_status`,
    `visits`,
    `anchor`,toStartOfMonth(toDate(created_at,'Europe/Paris')) as cohort_month,if(horizon_days is not null,toTimeZone(addDays(toTimeZone(anchor,'Europe/Paris'),horizon_days),'UTC'),NULL) as horizon,if(horizon_days is not null,horizon,{{ utc_var('case_as_of_boundary_at') }}) as observed,if(target_stage_id=0,created_at,arrayReduce('minOrNull',arrayMap(x->x.2,arrayFilter(x->x.1=target_stage_id and x.2 is not null and (followup_kind!='stage_transition' or x.2>anchor),visits)))) as reached,if(target_stage_id=0,created_at,arrayReduce('minOrNull',arrayMap(x->x.3,arrayFilter(x->x.1=target_stage_id and (followup_kind!='stage_transition' or x.2>anchor),visits)))) as reached_observed from anchors), maturities as (select `tenant_id`,
    `opportunity_id`,
