    `horizon`,
    `observed`,
    `reached`,
    `reached_observed`,max(horizon) over (partition by tenant_id,cohort_month,origin_type,followup_definition_id,horizon_days) as cohort_mature from horizons),
business as (select
    CAST(greatest(greatest(at_h.source_published_at,a.source_published_at,reached_p.source_published_at),hline.lineage_published) AS Nullable(DateTime64(3,'UTC'))) AS `source_published_at`,
    CAST(arraySort(arrayDistinct(arrayConcat(arraySort(arrayDistinct(arrayFilter(x->x is not null,arrayConcat(ifNull(at_h.source_version_keys,[]),ifNull(a.source_version_keys,[]),ifNull(reached_p.source_version_keys,[]))))),ifNull(hline.lineage_keys,[])))) AS Array(String)) AS `source_version_keys`,
    CAST(x.tenant_id AS String) AS `tenant_id`,
    CAST(x.opportunity_id AS Int64) AS `opportunity_id`,
    CAST(x.opportunity_key AS String) AS `opportunity_key`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('followup_v1',tuple('opportunity_key','String',if(isNull(opportunity_key),'1','0'),ifNull(toString(opportunity_key),'')),tuple('followup_definition_version_key','String',if(isNull(followup_definition_version_key),'1','0'),ifNull(toString(followup_definition_version_key),'')),tuple('anchor_key','String',if(isNull(anchor_key),'1','0'),ifNull(toString(anchor_key),'')),tuple('observation_at','Nullable(DateTime64(3,\'UTC\'))',if(isNull(x.observed),'1','0'),ifNull(toString(toUnixTimestamp64Milli(x.observed)),'')))))))) AS String) AS `followup_key`,
    CAST(x.followup_definition_id AS String) AS `followup_definition_id`,
    CAST(x.followup_definition_key AS String) AS `followup_definition_key`,
    CAST(x.followup_definition_version_key AS String) AS `followup_definition_version_key`,
    CAST(x.followup_kind AS String) AS `followup_kind`,
    CAST(x.funnel_position AS Nullable(UInt16)) AS `funnel_position`,
    CAST(x.previous_target_stage_id AS Nullable(Int64)) AS `previous_target_stage_id`,
    CAST(x.created_at AS Nullable(DateTime64(3,'UTC'))) AS `created_at`,
    CAST(x.cohort_month AS Nullable(Date)) AS `cohort_month`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('anchor_v1',tuple('opportunity_key','String',if(isNull(x.opportunity_key),'1','0'),ifNull(toString(x.opportunity_key),'')),tuple('anchor_at','Nullable(DateTime64(3,\'UTC\'))',if(isNull(x.anchor),'1','0'),ifNull(toString(toUnixTimestamp64Milli(x.anchor)),'')))))))) AS String) AS `anchor_key`,
    CAST(x.anchor AS Nullable(DateTime64(3,'UTC'))) AS `anchor_at`,
    CAST(x.source_stage_id AS Nullable(Int64)) AS `source_stage_id`,
    CAST(x.target_stage_id AS Nullable(Int64)) AS `target_stage_id`,
    CAST(if(x.target_stage_id is not null and x.target_stage_id!=0,lower(hex(SHA256(toJSONString(materialize(tuple('stage_v1',tuple('tenant_id','String',if(isNull(x.tenant_id),'1','0'),ifNull(toString(x.tenant_id),'')),tuple('stage_id','Int64',if(isNull(x.target_stage_id),'1','0'),ifNull(toString(x.target_stage_id),'')))))))),NULL) AS Nullable(String)) AS `target_stage_key`,
    CAST(if(x.target_stage_id!=0,reached_p.stage_version_key,NULL) AS Nullable(String)) AS `target_stage_version_key`,
    CAST(x.horizon_days AS Nullable(UInt16)) AS `horizon_days`,
    CAST(x.horizon AS Nullable(DateTime64(3,'UTC'))) AS `horizon_at`,
    CAST(x.observed AS Nullable(DateTime64(3,'UTC'))) AS `observation_at`,
    CAST(x.cohort_mature AS Nullable(DateTime64(3,'UTC'))) AS `cohort_mature_at`,
    CAST(if(x.horizon is null,true,x.horizon<={{ utc_var('case_as_of_boundary_at') }}) AS Nullable(Bool)) AS `is_mature`,
    CAST(if(x.horizon is null,true,x.cohort_mature<={{ utc_var('case_as_of_boundary_at') }}) AS Nullable(Bool)) AS `is_cohort_mature`,
    CAST(x.anchor is not null AS Nullable(Bool)) AS `is_eligible`,
    CAST(at_h.period_key is not null and not ifNull(at_h.is_source_deleted,true) and (x.horizon is null or x.horizon<{{ utc_var('case_as_of_boundary_at') }}) AS Nullable(Bool)) AS `is_observable`,
    CAST(x.first_at AS Nullable(DateTime64(3,'UTC'))) AS `coverage_start_at`,
    CAST({{ utc_var('case_as_of_boundary_at') }} AS Nullable(DateTime64(3,'UTC'))) AS `coverage_end_at`,
    CAST(is_observable and ifNull(at_h.is_history_complete,false) AS Nullable(Bool)) AS `is_history_complete`,
    CAST(x.reached AS Nullable(DateTime64(3,'UTC'))) AS `first_reached_at`,
    CAST(x.reached_observed AS Nullable(DateTime64(3,'UTC'))) AS `first_reached_observed_at`,
    CAST(if(x.followup_kind='stage_transition',x.anchor,NULL) AS Nullable(DateTime64(3,'UTC'))) AS `previous_stage_first_reached_at`,
    CAST(multiIf(if(x.observed={{ utc_var('case_as_of_boundary_at') }},x.reached_observed<x.observed,x.reached_observed<=x.observed),true,is_observable and x.anchor>=x.first_at,false,NULL) AS Nullable(Bool)) AS `reached_target`,
    CAST(if(not is_cohort_mature,NULL,if(is_observable and at_h.outcome_category is not null,at_h.outcome_category,'unknown')) AS Nullable(String)) AS `issue_at_horizon`,
    CAST(lower(hex(SHA256(toJSONString(materialize(tuple('population_v1',tuple('opportunity_key','String',if(isNull(x.opportunity_key),'1','0'),ifNull(toString(x.opportunity_key),'')),tuple('definition_key','String',if(isNull(x.followup_definition_version_key),'1','0'),ifNull(toString(x.followup_definition_version_key),'')),tuple('horizon_days','Nullable(UInt16)',if(isNull(x.horizon_days),'1','0'),ifNull(toString(x.horizon_days),'')))))))) AS String) AS `population_count_key`,
    CAST(if(is_cohort_mature and is_eligible,1,NULL) AS Nullable(UInt8)) AS `denominator_contribution`,
    CAST(if(denominator_contribution=1,toUInt8(reached_target),NULL) AS Nullable(UInt8)) AS `converted_contribution`,
    CAST(if(denominator_contribution=1,toUInt8(issue_at_horizon='open'),NULL) AS Nullable(UInt8)) AS `open_contribution`,
    CAST(if(denominator_contribution=1,toUInt8(issue_at_horizon='won'),NULL) AS Nullable(UInt8)) AS `won_contribution`,
    CAST(if(denominator_contribution=1,toUInt8(issue_at_horizon='lost'),NULL) AS Nullable(UInt8)) AS `lost_contribution`,
    CAST(if(denominator_contribution=1,toUInt8(issue_at_horizon='abandoned'),NULL) AS Nullable(UInt8)) AS `abandoned_contribution`,
    CAST(if(denominator_contribution=1,toUInt8(issue_at_horizon='unqualified'),NULL) AS Nullable(UInt8)) AS `unqualified_contribution`,
    CAST(if(denominator_contribution=1,toUInt8(issue_at_horizon='unknown'),NULL) AS Nullable(UInt8)) AS `unknown_contribution`,
    CAST(a.company_id AS Nullable(Int64)) AS `company_id`,
    CAST(a.company_key AS Nullable(String)) AS `company_key`,
    CAST(a.company_version_key AS Nullable(String)) AS `company_version_key`,
    CAST(x.origin_type AS Nullable(Int64)) AS `sale_type_id`,
    CAST(a.sale_type_key AS Nullable(String)) AS `sale_type_key`,
    CAST(a.sale_type_version_key AS Nullable(String)) AS `sale_type_version_key`,
    CAST(a.employee_id AS Nullable(Int64)) AS `employee_id`,
    CAST(a.employee_key AS Nullable(String)) AS `employee_key`,
    CAST(a.employee_version_key AS Nullable(String)) AS `employee_version_key`,
    CAST(a.team_id AS Nullable(Int64)) AS `team_id`,
    CAST(a.team_key AS Nullable(String)) AS `team_key`,
    CAST(a.team_version_key AS Nullable(String)) AS `team_version_key`,
    CAST(a.sales_segment AS Nullable(String)) AS `sales_segment`,
    CAST(ifNull(a.is_team_calculable,false) AS Bool) AS `is_team_calculable`,
    CAST(a.acquisition_channel_key AS Nullable(String)) AS `acquisition_channel_key`,
    CAST(a.channel_version_key AS Nullable(String)) AS `channel_version_key`,
    CAST(a.channel_candidate_code AS Nullable(String)) AS `channel_candidate_code`,
    CAST(ifNull(a.is_channel_calculable,false) AS Bool) AS `is_channel_calculable`,
    CAST(ifNull(a.attribution_status,'missing_temporal_context') AS String) AS `attribution_status`,
    CAST(multiIf(not is_cohort_mature,'blocked',not is_observable,'partial','ready') AS String) AS `calculation_status`,
    CAST(multiIf(not is_cohort_mature,'non_mature',not is_observable,'incomplete_history',NULL) AS Nullable(String)) AS `status_reason`
from maturities x left join p at_h on x.tenant_id=at_h.tenant_id and x.opportunity_id=at_h.opportunity_id and if(x.observed={{ utc_var('case_as_of_boundary_at') }},at_h.valid_from_at<x.observed and (at_h.valid_to_at is null or at_h.valid_to_at>=x.observed),x.observed>=at_h.valid_from_at and (at_h.valid_to_at is null or x.observed<at_h.valid_to_at)) left join p a on x.tenant_id=a.tenant_id and x.opportunity_id=a.opportunity_id and x.anchor>=a.valid_from_at and (a.valid_to_at is null or x.anchor<a.valid_to_at) left join p reached_p on x.tenant_id=reached_p.tenant_id and x.opportunity_id=reached_p.opportunity_id and x.reached_observed>=reached_p.valid_from_at and (reached_p.valid_to_at is null or x.reached_observed<reached_p.valid_to_at) left join histories hline on x.tenant_id=hline.tenant_id and x.opportunity_id=hline.opportunity_id),
